/* ============================================
   GlobalStone — Global Commercial Real Estate
   Design System & Styles
   ============================================ */

/* CSS Variables */
:root {
  --primary-dark: #0A1628;
  --primary-green: #003F2D;
  --secondary-teal: #012A2D;
  --accent-gold: #C9A96E;
  --accent-teal: #0D7377;
  --neutral-light: #E6E6E6;
  --neutral-mid: #8A9199;
  --neutral-dark: #3D4550;
  --white: #FFFFFF;
  --off-white: #F5F6F7;
  --surface: #F8F9FA;
  --border: #DEE2E6;
  --shadow-sm: 0 1px 3px rgba(10, 22, 40, 0.08);
  --shadow-md: 0 4px 16px rgba(10, 22, 40, 0.10);
  --shadow-lg: 0 12px 40px rgba(10, 22, 40, 0.14);
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --transition: all 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  --font-serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --max-width: 1280px;
  --header-height: 72px;
}

/* Reset & Base */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.6;
  color: var(--primary-dark);
  background: var(--white);
}

img {
  max-width: 100%;
  height: auto;
  display: block;
}

a {
  color: inherit;
  text-decoration: none;
  transition: var(--transition);
}

ul, ol {
  list-style: none;
}

button {
  font-family: inherit;
  cursor: pointer;
  border: none;
  background: none;
}

/* Typography */
h1, h2, h3, h4, h5, h6 {
  font-family: var(--font-serif);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: -0.02em;
}

h1 { font-size: clamp(2.25rem, 5vw, 3.75rem); }
h2 { font-size: clamp(1.75rem, 3.5vw, 2.5rem); }
h3 { font-size: clamp(1.25rem, 2vw, 1.5rem); }
h4 { font-size: 1.125rem; }

p {
  color: var(--neutral-dark);
  line-height: 1.7;
}

.text-sm { font-size: 0.875rem; }
.text-xs { font-size: 0.75rem; }
.text-lg { font-size: 1.125rem; }
.font-sans { font-family: var(--font-sans); }
.font-serif { font-family: var(--font-serif); }

/* Layout */
.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.section {
  padding: 80px 0;
}

.section-sm {
  padding: 48px 0;
}

.section-dark {
  background: var(--primary-dark);
  color: var(--white);
}

.section-dark p {
  color: var(--neutral-mid);
}

.section-green {
  background: var(--primary-green);
  color: var(--white);
}

.section-green p {
  color: rgba(255,255,255,0.75);
}

/* Header */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: var(--header-height);
  background: var(--white);
  border-bottom: 1px solid var(--border);
  z-index: 1000;
  transition: var(--transition);
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  font-family: var(--font-serif);
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--primary-dark);
  letter-spacing: -0.03em;
}

.logo span {
  color: var(--accent-gold);
}

/* Desktop Nav */
.nav-desktop {
  display: flex;
  align-items: center;
  gap: 32px;
}

.nav-link {
  font-size: 0.875rem;
  font-weight: 500;
  color: var(--neutral-dark);
  letter-spacing: 0.01em;
  position: relative;
  padding: 4px 0;
}

.nav-link:hover {
  color: var(--primary-dark);
}

.nav-link::after {
  content: '';
  position: absolute;
  bottom: 0;
  left: 0;
  width: 0;
  height: 2px;
  background: var(--accent-gold);
  transition: var(--transition);
}

.nav-link:hover::after {
  width: 100%;
}

.nav-link.has-dropdown {
  display: flex;
  align-items: center;
  gap: 6px;
}

.nav-link.has-dropdown svg {
  width: 14px;
  height: 14px;
  transition: transform 0.2s;
}

.nav-link.has-dropdown[aria-expanded="true"] svg {
  transform: rotate(180deg);
}

/* Mega Menu */
.mega-menu {
  position: absolute;
  top: var(--header-height);
  left: 0;
  right: 0;
  background: var(--white);
  border-bottom: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  opacity: 0;
  visibility: hidden;
  transform: translateY(-8px);
  transition: var(--transition);
  z-index: 999;
}

.mega-menu.active {
  opacity: 1;
  visibility: visible;
  transform: translateY(0);
}

.mega-menu-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 40px 24px;
  display: grid;
  grid-template-columns: 1.5fr 1fr;
  gap: 48px;
}

.mega-menu-title {
  font-family: var(--font-sans);
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--neutral-mid);
  margin-bottom: 16px;
}

.mega-menu-list {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px 24px;
}

.mega-menu-list.full {
  grid-template-columns: repeat(1, 1fr);
}

.mega-menu-item {
  display: block;
  padding: 10px 0;
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--primary-dark);
  border-bottom: 1px solid transparent;
  transition: var(--transition);
}

.mega-menu-item:hover {
  color: var(--accent-gold);
  border-bottom-color: var(--accent-gold);
}

.mega-menu-item-desc {
  font-size: 0.8125rem;
  color: var(--neutral-mid);
  margin-top: 2px;
  font-weight: 400;
}

/* Mobile Nav Toggle */
.nav-toggle {
  display: none;
  flex-direction: column;
  gap: 5px;
  padding: 8px;
  background: none;
  border: none;
  cursor: pointer;
}

.nav-toggle span {
  display: block;
  width: 24px;
  height: 2px;
  background: var(--primary-dark);
  transition: var(--transition);
}

.nav-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: rotate(45deg) translate(5px, 5px);
}

.nav-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.nav-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: rotate(-45deg) translate(5px, -5px);
}

/* Mobile Nav Panel */
.nav-mobile {
  display: none;
  position: fixed;
  top: var(--header-height);
  left: 0;
  right: 0;
  bottom: 0;
  background: var(--white);
  z-index: 998;
  overflow-y: auto;
  padding: 24px;
}

.nav-mobile.active {
  display: block;
}

.mobile-nav-item {
  border-bottom: 1px solid var(--border);
}

.mobile-nav-link {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 16px 0;
  font-size: 1rem;
  font-weight: 500;
  color: var(--primary-dark);
  width: 100%;
}

.mobile-nav-link svg {
  width: 18px;
  height: 18px;
  transition: transform 0.2s;
}

.mobile-nav-link[aria-expanded="true"] svg {
  transform: rotate(180deg);
}

.mobile-submenu {
  display: none;
  padding: 0 0 16px 16px;
}

.mobile-submenu.active {
  display: block;
}

.mobile-submenu a {
  display: block;
  padding: 10px 0;
  font-size: 0.9375rem;
  color: var(--neutral-dark);
}

.mobile-submenu a:hover {
  color: var(--accent-gold);
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  padding: 14px 28px;
  font-size: 0.875rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  border-radius: var(--radius-sm);
  transition: var(--transition);
  cursor: pointer;
}

.btn-primary {
  background: var(--accent-gold);
  color: var(--primary-dark);
}

.btn-primary:hover {
  background: #b8995a;
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: transparent;
  color: var(--white);
  border: 1.5px solid rgba(255,255,255,0.4);
}

.btn-secondary:hover {
  background: rgba(255,255,255,0.08);
  border-color: rgba(255,255,255,0.7);
}

.btn-dark {
  background: var(--primary-dark);
  color: var(--white);
}

.btn-dark:hover {
  background: var(--secondary-teal);
}

.btn-outline-dark {
  background: transparent;
  color: var(--primary-dark);
  border: 1.5px solid var(--primary-dark);
}

.btn-outline-dark:hover {
  background: var(--primary-dark);
  color: var(--white);
}

.btn-sm {
  padding: 10px 20px;
  font-size: 0.8125rem;
}

/* Hero */
.hero {
  position: relative;
  min-height: 80vh;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  margin-top: var(--header-height);
}

.hero-bg {
  position: absolute;
  inset: 0;
  background-size: cover;
  background-position: center;
  z-index: 0;
}

.hero-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(10, 22, 40, 0.88) 0%, rgba(10, 22, 40, 0.65) 100%);
  z-index: 1;
}

.hero-content {
  position: relative;
  z-index: 2;
  max-width: 800px;
  text-align: center;
  padding: 0 24px;
  color: var(--white);
}

.hero-label {
  display: inline-block;
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--accent-gold);
  margin-bottom: 20px;
}

.hero-title {
  font-size: clamp(2.5rem, 6vw, 4.5rem);
  font-weight: 600;
  line-height: 1.1;
  margin-bottom: 24px;
  color: var(--white);
}

.hero-subtitle {
  font-size: clamp(1rem, 2vw, 1.25rem);
  color: rgba(255,255,255,0.8);
  margin-bottom: 36px;
  max-width: 600px;
  margin-left: auto;
  margin-right: auto;
}

.hero-actions {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
}

/* Announcement Banner */
.announcement-banner {
  background: var(--secondary-teal);
  color: var(--white);
  padding: 16px 0;
}

.announcement-banner-inner {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 16px;
  flex-wrap: wrap;
  text-align: center;
}

.announcement-banner p {
  color: rgba(255,255,255,0.9);
  font-size: 0.9375rem;
}

.announcement-banner a {
  color: var(--accent-gold);
  font-weight: 600;
  font-size: 0.875rem;
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Cards */
.card {
  background: var(--white);
  border-radius: var(--radius-md);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border);
  transition: var(--transition);
}

.card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.card-image {
  aspect-ratio: 16/10;
  background: var(--neutral-light);
  overflow: hidden;
}

.card-image img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.4s;
}

.card:hover .card-image img {
  transform: scale(1.04);
}

.card-body {
  padding: 24px;
}

.card-tag {
  font-size: 0.6875rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--accent-gold);
  margin-bottom: 10px;
}

.card-title {
  font-family: var(--font-serif);
  font-size: 1.125rem;
  font-weight: 600;
  line-height: 1.3;
  margin-bottom: 8px;
  color: var(--primary-dark);
}

.card-text {
  font-size: 0.9375rem;
  color: var(--neutral-dark);
  line-height: 1.6;
}

.card-meta {
  font-size: 0.8125rem;
  color: var(--neutral-mid);
  margin-top: 12px;
}

/* Grids */
.grid-3 {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.grid-2 {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 24px;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

/* Section Header */
.section-header {
  text-align: center;
  max-width: 700px;
  margin: 0 auto 56px;
}

.section-header h2 {
  margin-bottom: 16px;
  color: var(--primary-dark);
}

.section-header p {
  font-size: 1.0625rem;
  color: var(--neutral-dark);
}

/* About Statement */
.about-statement {
  background: var(--off-white);
}

.about-statement-inner {
  max-width: 900px;
  margin: 0 auto;
  text-align: center;
}

.about-statement h2 {
  font-size: clamp(1.5rem, 3vw, 2.25rem);
  margin-bottom: 24px;
  color: var(--primary-dark);
}

.about-statement p {
  font-size: 1.0625rem;
  margin-bottom: 28px;
  color: var(--neutral-dark);
}

/* What We Do Tabs */
.what-we-do {
  background: var(--white);
}

.tabs-container {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 48px;
  max-width: 1000px;
  margin: 0 auto;
}

.tab-list {
  display: flex;
  flex-direction: column;
  gap: 4px;
  border-right: 2px solid var(--border);
  padding-right: 24px;
}

.tab-btn {
  text-align: left;
  padding: 16px 20px;
  font-size: 1rem;
  font-weight: 500;
  color: var(--neutral-mid);
  border-radius: var(--radius-sm);
  transition: var(--transition);
  position: relative;
}

.tab-btn:hover {
  color: var(--primary-dark);
  background: var(--off-white);
}

.tab-btn.active {
  color: var(--primary-dark);
  background: var(--off-white);
  font-weight: 600;
}

.tab-btn.active::after {
  content: '';
  position: absolute;
  right: -26px;
  top: 50%;
  transform: translateY(-50%);
  width: 2px;
  height: 32px;
  background: var(--accent-gold);
}

.tab-panel {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-panel.active {
  display: block;
}

.tab-panel h3 {
  margin-bottom: 16px;
  color: var(--primary-dark);
}

.tab-panel p {
  margin-bottom: 24px;
  color: var(--neutral-dark);
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateX(8px); }
  to { opacity: 1; transform: translateX(0); }
}

/* Newsletter */
.newsletter {
  background: var(--primary-dark);
  color: var(--white);
  text-align: center;
}

.newsletter h2 {
  color: var(--white);
  margin-bottom: 12px;
}

.newsletter p {
  color: rgba(255,255,255,0.7);
  margin-bottom: 28px;
}

/* Commitment */
.commitment-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 24px;
}

.commitment-card {
  padding: 32px 24px;
  border-radius: var(--radius-md);
  background: var(--white);
  border: 1px solid var(--border);
  transition: var(--transition);
}

.commitment-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.commitment-card h4 {
  font-family: var(--font-serif);
  font-size: 1.125rem;
  margin-bottom: 12px;
  color: var(--primary-dark);
}

.commitment-card p {
  font-size: 0.9375rem;
  color: var(--neutral-dark);
  margin-bottom: 16px;
}

.commitment-card a {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent-gold);
}

.commitment-card a:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Service Categories */
.service-categories {
  background: var(--off-white);
}

.service-card {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 36px 28px;
  border: 1px solid var(--border);
  transition: var(--transition);
  display: flex;
  flex-direction: column;
  height: 100%;
}

.service-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-3px);
}

.service-card h3 {
  font-family: var(--font-serif);
  font-size: 1.25rem;
  margin-bottom: 12px;
  color: var(--primary-dark);
}

.service-card p {
  font-size: 0.9375rem;
  color: var(--neutral-dark);
  margin-bottom: 20px;
  flex-grow: 1;
}

.service-card a {
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--accent-gold);
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.service-card a:hover {
  text-decoration: underline;
  text-underline-offset: 3px;
}

/* Capabilities */
.capability-card {
  padding: 32px;
  border-radius: var(--radius-md);
  background: var(--white);
  border: 1px solid var(--border);
  transition: var(--transition);
}

.capability-card:hover {
  box-shadow: var(--shadow-md);
  border-color: var(--accent-gold);
}

.capability-card h4 {
  font-family: var(--font-serif);
  font-size: 1.125rem;
  margin-bottom: 10px;
  color: var(--primary-dark);
}

.capability-card p {
  font-size: 0.9375rem;
  color: var(--neutral-dark);
}

/* Partnership Highlight */
.partnership-highlight {
  background: var(--secondary-teal);
  color: var(--white);
  padding: 64px 0;
}

.partnership-highlight-inner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.partnership-highlight h2 {
  color: var(--white);
  margin-bottom: 20px;
}

.partnership-highlight p {
  color: rgba(255,255,255,0.8);
  font-size: 1.0625rem;
  line-height: 1.7;
}

/* Footer */
.footer {
  background: var(--primary-dark);
  color: var(--white);
  padding: 64px 0 32px;
}

.footer-grid {
  display: grid;
  grid-template-columns: 1.5fr repeat(3, 1fr);
  gap: 48px;
  margin-bottom: 48px;
}

.footer-brand .logo {
  color: var(--white);
  margin-bottom: 16px;
  display: inline-block;
}

.footer-brand p {
  color: var(--neutral-mid);
  font-size: 0.9375rem;
  max-width: 300px;
}

.footer-col h4 {
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--neutral-mid);
  margin-bottom: 20px;
}

.footer-col a {
  display: block;
  padding: 6px 0;
  font-size: 0.9375rem;
  color: rgba(255,255,255,0.7);
}

.footer-col a:hover {
  color: var(--accent-gold);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.1);
  padding-top: 24px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-wrap: wrap;
  gap: 16px;
}

.footer-bottom p {
  font-size: 0.8125rem;
  color: var(--neutral-mid);
}

.footer-bottom-links {
  display: flex;
  gap: 24px;
}

.footer-bottom-links a {
  font-size: 0.8125rem;
  color: var(--neutral-mid);
}

.footer-bottom-links a:hover {
  color: var(--accent-gold);
}

/* Insights */
.insight-card {
  display: flex;
  flex-direction: column;
  height: 100%;
}

/* Featured Insights Row */
.featured-insights-row {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

/* Property Types CTA */
.property-types {
  background: var(--off-white);
}

.property-types-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 16px;
}

.property-type-card {
  background: var(--white);
  border-radius: var(--radius-md);
  padding: 28px 20px;
  text-align: center;
  border: 1px solid var(--border);
  transition: var(--transition);
}

.property-type-card:hover {
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

.property-type-card h4 {
  font-family: var(--font-serif);
  font-size: 1rem;
  color: var(--primary-dark);
}

/* Testimonial */
.testimonial {
  background: var(--white);
}

.testimonial-inner {
  max-width: 800px;
  margin: 0 auto;
  text-align: center;
}

.testimonial blockquote {
  font-family: var(--font-serif);
  font-size: clamp(1.25rem, 2.5vw, 1.75rem);
  font-style: italic;
  line-height: 1.5;
  color: var(--primary-dark);
  margin-bottom: 24px;
}

.testimonial cite {
  font-style: normal;
  font-size: 0.9375rem;
  color: var(--neutral-mid);
}

/* Deal Flow CTA */
.deal-flow {
  background: var(--primary-green);
  color: var(--white);
  text-align: center;
}

.deal-flow h2 {
  color: var(--white);
  margin-bottom: 12px;
}

.deal-flow p {
  color: rgba(255,255,255,0.8);
  margin-bottom: 28px;
}

/* Related Services / Topics */
.related-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.related-list a {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 20px;
  background: var(--white);
  border: 1px solid var(--border);
  border-radius: var(--radius-sm);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--primary-dark);
  transition: var(--transition);
}

.related-list a:hover {
  border-color: var(--accent-gold);
  color: var(--accent-gold);
}

/* Sidebar Layout */
.sidebar-layout {
  display: grid;
  grid-template-columns: 1fr 320px;
  gap: 48px;
}

.sidebar-section h4 {
  font-family: var(--font-sans);
  font-size: 0.8125rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--neutral-mid);
  margin-bottom: 16px;
}

/* Carousel */
.carousel {
  position: relative;
  overflow: hidden;
}

.carousel-track {
  display: flex;
  transition: transform 0.4s ease;
}

.carousel-slide {
  min-width: 100%;
  padding: 0 12px;
}

.carousel-controls {
  display: flex;
  justify-content: center;
  gap: 12px;
  margin-top: 24px;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 1px solid var(--border);
  background: var(--white);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: var(--transition);
}

.carousel-btn:hover {
  background: var(--primary-dark);
  border-color: var(--primary-dark);
  color: var(--white);
}

/* Responsive */
@media (max-width: 1024px) {
  .grid-4 { grid-template-columns: repeat(2, 1fr); }
  .commitment-grid { grid-template-columns: repeat(2, 1fr); }
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .sidebar-layout { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(3, 1fr); }
}

@media (max-width: 768px) {
  .nav-desktop { display: none; }
  .nav-toggle { display: flex; }
  .grid-3, .grid-2, .grid-4 { grid-template-columns: 1fr; }
  .featured-insights-row { grid-template-columns: 1fr; }
  .tabs-container { grid-template-columns: 1fr; }
  .tab-list {
    flex-direction: row;
    border-right: none;
    border-bottom: 2px solid var(--border);
    padding-right: 0;
    padding-bottom: 16px;
    overflow-x: auto;
  }
  .tab-btn { white-space: nowrap; }
  .tab-btn.active::after {
    right: auto;
    left: 50%;
    top: auto;
    bottom: -18px;
    transform: translateX(-50%);
    width: 32px;
    height: 2px;
  }
  .commitment-grid { grid-template-columns: 1fr; }
  .footer-grid { grid-template-columns: 1fr; }
  .footer-bottom { flex-direction: column; text-align: center; }
  .mega-menu-inner { grid-template-columns: 1fr; }
  .property-types-grid { grid-template-columns: repeat(2, 1fr); }
  .section { padding: 56px 0; }
  .hero { min-height: 70vh; }
}

@media (max-width: 480px) {
  .property-types-grid { grid-template-columns: 1fr; }
  .hero-actions { flex-direction: column; align-items: center; }
  .btn { width: 100%; max-width: 280px; }
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

/* ============================================
   GlobalStone — Global Commercial Real Estate
   Interactive Scripts
   ============================================ */

document.addEventListener('DOMContentLoaded', () => {
  initMobileNav();
  initMegaMenu();
  initTabs();
  initCarousels();
  initHeaderScroll();
});

/* Mobile Navigation */
function initMobileNav() {
  const toggle = document.querySelector('.nav-toggle');
  const mobileNav = document.querySelector('.nav-mobile');
  if (!toggle || !mobileNav) return;

  toggle.addEventListener('click', () => {
    const expanded = toggle.getAttribute('aria-expanded') === 'true';
    toggle.setAttribute('aria-expanded', !expanded);
    mobileNav.classList.toggle('active');
    document.body.style.overflow = !expanded ? 'hidden' : '';
  });

  // Accordion submenus
  mobileNav.querySelectorAll('.mobile-nav-link').forEach(link => {
    if (!link.hasAttribute('aria-expanded')) return;
    link.addEventListener('click', (e) => {
      e.preventDefault();
      const expanded = link.getAttribute('aria-expanded') === 'true';
      // Close others
      mobileNav.querySelectorAll('.mobile-nav-link[aria-expanded="true"]').forEach(l => {
        if (l !== link) {
          l.setAttribute('aria-expanded', 'false');
          l.nextElementSibling?.classList.remove('active');
        }
      });
      link.setAttribute('aria-expanded', !expanded);
      const submenu = link.nextElementSibling;
      if (submenu) submenu.classList.toggle('active');
    });
  });
}

/* Mega Menu */
function initMegaMenu() {
  const triggers = document.querySelectorAll('[data-mega-menu]');
  triggers.forEach(trigger => {
    const targetId = trigger.getAttribute('data-mega-menu');
    const menu = document.getElementById(targetId);
    if (!menu) return;

    let timeout;

    const open = () => {
      clearTimeout(timeout);
      trigger.setAttribute('aria-expanded', 'true');
      menu.classList.add('active');
    };

    const close = () => {
      timeout = setTimeout(() => {
        trigger.setAttribute('aria-expanded', 'false');
        menu.classList.remove('active');
      }, 150);
    };

    trigger.addEventListener('mouseenter', open);
    trigger.addEventListener('mouseleave', close);
    menu.addEventListener('mouseenter', () => clearTimeout(timeout));
    menu.addEventListener('mouseleave', close);

    trigger.addEventListener('click', (e) => {
      if (window.innerWidth >= 769) {
        e.preventDefault();
        const expanded = trigger.getAttribute('aria-expanded') === 'true';
        if (expanded) {
          trigger.setAttribute('aria-expanded', 'false');
          menu.classList.remove('active');
        } else {
          // Close other menus
          triggers.forEach(t => {
            if (t !== trigger) {
              t.setAttribute('aria-expanded', 'false');
              const m = document.getElementById(t.getAttribute('data-mega-menu'));
              m?.classList.remove('active');
            }
          });
          open();
        }
      }
    });
  });

  // Close on escape
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      triggers.forEach(t => {
        t.setAttribute('aria-expanded', 'false');
        const m = document.getElementById(t.getAttribute('data-mega-menu'));
        m?.classList.remove('active');
      });
    }
  });
}

/* Tabs */
function initTabs() {
  document.querySelectorAll('[data-tabs]').forEach(container => {
    const buttons = container.querySelectorAll('[data-tab]');
    const panels = container.querySelectorAll('[data-tab-panel]');

    buttons.forEach(btn => {
      btn.addEventListener('click', () => {
        const target = btn.getAttribute('data-tab');

        buttons.forEach(b => b.classList.remove('active'));
        panels.forEach(p => p.classList.remove('active'));

        btn.classList.add('active');
        const panel = container.querySelector(`[data-tab-panel="${target}"]`);
        if (panel) panel.classList.add('active');
      });
    });
  });
}

/* Carousels */
function initCarousels() {
  document.querySelectorAll('[data-carousel]').forEach(carousel => {
    const track = carousel.querySelector('.carousel-track');
    const slides = carousel.querySelectorAll('.carousel-slide');
    const prevBtn = carousel.querySelector('[data-carousel-prev]');
    const nextBtn = carousel.querySelector('[data-carousel-next]');
    if (!track || slides.length === 0) return;

    let current = 0;

    const update = () => {
      track.style.transform = `translateX(-${current * 100}%)`;
    };

    prevBtn?.addEventListener('click', () => {
      current = (current - 1 + slides.length) % slides.length;
      update();
    });

    nextBtn?.addEventListener('click', () => {
      current = (current + 1) % slides.length;
      update();
    });
  });
}

/* Header Scroll Effect */
function initHeaderScroll() {
  const header = document.querySelector('.header');
  if (!header) return;

  let lastScroll = 0;
  window.addEventListener('scroll', () => {
    const currentScroll = window.pageYOffset;
    if (currentScroll > 50) {
      header.style.boxShadow = '0 2px 12px rgba(10, 22, 40, 0.08)';
    } else {
      header.style.boxShadow = 'none';
    }
    lastScroll = currentScroll;
  });
}
